package main

// The registry half of --publishes and --subscribes: a message the registry
// declares travels on its producer channel's topic, in both directions, so a
// component scaffolded from the registry lands where the registry says the
// message is. A message the registry does not know keeps the template's
// default topic, the message name.

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// resolveMessageChannel returns the topic message travels on according to the
// registry, or "" when the template's default applies: no message, no
// registry configured, a registry that does not declare the message, or one
// that names no producer channel for it. An unreachable registry is a warning,
// not a failure — an internal message must still scaffold offline — and the
// warning says which topic the component gets instead.
func resolveMessageChannel(ctx context.Context, stderr io.Writer, message string, sets map[string]any) (string, error) {
	if message == "" {
		return "", nil
	}
	explicit, err := explicitChannel(sets)
	if err != nil {
		return "", err
	}
	url, err := resolveRegistryURL("")
	if err != nil {
		return "", nil
	}
	client, err := newXRegistryClient(url)
	if err != nil {
		return "", err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		fmt.Fprintf(stderr, "warning: %v\n%s is wired on the template's default topic; check the registry declares no other channel for it\n", err, message)
		return "", nil
	}
	return registryTopic(doc, message, explicit)
}

// explicitChannel reads the topic the user chose with --set. The templates
// take it as the topic parameter and derive the recorded channel from it, so
// channel is accepted as the same choice; naming both with different values is
// a usage error rather than a guess.
func explicitChannel(sets map[string]any) (string, error) {
	topic, _ := sets[template.KeyTopic].(string)
	channel, _ := sets[template.KeyChannel].(string)
	if topic != "" && channel != "" && topic != channel {
		return "", newUsageErrorf("--set topic=%s and --set channel=%s name different topics; set one", topic, channel)
	}
	if topic != "" {
		return topic, nil
	}
	return channel, nil
}

// registryTopic decides the topic for message from the registry export. The
// registry's producer channel decides; an explicit choice must be one of the
// producer channels' topics, and a message produced on several topics needs
// one. Only the topic half is returned: a scaffold record never names a
// pub/sub, which belongs to the system the component joins.
func registryTopic(doc *xregistry.Export, message, explicit string) (string, error) {
	_, group, err := xregistry.FindMessage(doc, message)
	var notFound *xregistry.MessageNotFoundError
	if errors.As(err, &notFound) {
		return "", nil
	}
	if err != nil {
		return "", newUsageErrorf("%v", err)
	}
	channels := xregistry.ProducerChannels(doc, group.ID)
	topics := channelTopics(channels)
	switch {
	case len(topics) == 0:
		return "", nil
	case explicit != "":
		for _, t := range topics {
			if t == explicit {
				return explicit, nil
			}
		}
		return "", newUsageErrorf("topic %q conflicts with the registry: %s is produced on %s\ndrop --set topic=%s to use the registry's channel, or correct the registry's producer endpoint",
			explicit, message, strings.Join(channels, ", "), explicit)
	case len(topics) == 1:
		return topics[0], nil
	default:
		return "", newUsageErrorf("message %q has %d producer channels in the registry: %s\npass --set topic=<topic> to choose one", message, len(topics), strings.Join(channels, ", "))
	}
}

// channelTopics projects <pubsub>/<topic> channels onto their distinct topics.
func channelTopics(channels []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, c := range channels {
		_, topic, err := xregistry.SplitChannel(c)
		if err != nil || seen[topic] {
			continue
		}
		seen[topic] = true
		out = append(out, topic)
	}
	sort.Strings(out)
	return out
}

