// ErrChannelConflict reports a --set topic that names another topic than the
// one the caller decided the message travels on.
var ErrChannelConflict = errors.New("topic conflicts with the message's channel")

// seedTopic feeds the topic a component's message travels on into the
// template's topic parameter. Templates record the channel as a derived
// value — the topic parameter, else the message name — so a --set channel
// would be overwritten by the derivation; it is taken as the topic instead.
// A channel decided by the caller (the registry's) seeds the topic, and a
// template without a topic parameter cannot record it: refusing beats
// recording a channel the registry contradicts.
func seedTopic(tmpl *Template, sets map[string]any, message, channel string) error {
	_, hasTopic := indexFields(tmpl.Fields())[KeyTopic]
	_, derivesChannel := tmpl.Spec.Values[KeyChannel]
	if hasTopic && derivesChannel {
		if explicit, ok := sets[KeyChannel].(string); ok && explicit != "" {
			if topic, ok := sets[KeyTopic].(string); ok && topic != "" && topic != explicit {
				return fmt.Errorf("template %q: %w\\n--set topic=%s and --set channel=%s name different topics; set one", tmpl.Metadata.Name, ErrChannelConflict, topic, explicit)
			}
			sets[KeyTopic] = explicit
			delete(sets, KeyChannel)
		}
	}
	if message == "" || channel == "" {
		return nil
	}
	if !hasTopic {
		if channel == message {
			return nil
		}
		return fmt.Errorf("template %q declares no %s parameter, so %s cannot be wired on its channel %q\\nuse a template release whose manifest declares %s", tmpl.Metadata.Name, KeyTopic, message, channel, KeyTopic)
	}
	if topic, ok := sets[KeyTopic].(string); ok && topic != "" && topic != channel {
		return fmt.Errorf("template %q: %w\\n%s travels on %q, but topic was set to %q; remove the conflicting value or make them match", tmpl.Metadata.Name, ErrChannelConflict, message, channel, topic)
	}
	sets[KeyTopic] = channel
	return nil
}

func cmpOr(a, b string) string {
	if a != "" {
		return a
	}
	return b
}
