// the record's payloadType.
func ReadPublications(e ScaffoldEntry) ([]Publication, error) {
	message, err := ReadPublishesMessage(e)
	if err != nil {
		return nil, err
	}
	payloadType, err := RecordValueDefault(e, KeyPayloadType, "")
	if err != nil {
		return nil, err
	}
