	record := filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
	list, ok := raw.([]any)
	if !ok {
		return nil, fmt.Errorf("%s: values.%s must be a list of {message, payloadType}", record, KeyPublications)
	}
	out := []Publication{primary}
	seen := map[string]bool{}
	for i, item := range list {
		m, ok := item.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("%s: values.%s[%d] has type %T, expected an object", record, KeyPublications, i, item)
		}
		name, _ := m[KeyMessage].(string)
		if name == "" {
			return nil, fmt.Errorf("%s: values.%s[%d].%s is missing", record, KeyPublications, i, KeyMessage)
		}
		if seen[name] {
			return nil, fmt.Errorf("%s: values.%s names message %q twice", record, KeyPublications, name)
		}
		seen[name] = true
		typ, _ := m[KeyPayloadType].(string)
		if name == message {
			if typ != "" && payloadType != "" && typ != payloadType {
				return nil, fmt.Errorf("%s: values.%s types %q as %q, but values.%s is %q; make them match", record, KeyPublications, name, typ, KeyPayloadType, payloadType)
			}
			if out[0].PayloadType == "" {
				out[0].PayloadType = typ
			}
			continue
		}
		out = append(out, Publication{Message: name, PayloadType: typ})
	}
	if len(list) > 0 && !seen[message] {
		return nil, fmt.Errorf("%s: values.%s does not name the published message %q\\nadd an entry for it, or change publishes to the message the pipeline produces", record, KeyPublications, message)
	}
	for i := range out {
		out[i] = withDerivedType(out[i])
	}
	return out, nil
}

