package system

import (
	"reflect"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// A record whose payloadType differs from the derivation — a contract renamed
// in Contracts, or named after its schema — types its message by the record,
// in the message list sys create renders Messages.cs from.
func TestAssembleTypesTheMessageByTheRecordedPayloadType(t *testing.T) {
	e := extractor("kurstillfalle", "kurstillfalle", "se.ladok.utbildning.kurstillfalle.klarmarkerat.v1")
	e.Values[template.KeyPayloadType] = "KurstillfalleKlarmarkerat"
	model, err := Assemble([]template.ScaffoldEntry{e}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}
	if got := model.Messages[0].Contract; got != "KurstillfalleKlarmarkerat" {
		t.Errorf("message contract = %q, want the recorded payloadType", got)
	}
	if got := model.Topics[0].Contract; got != "KurstillfalleKlarmarkerat" {
		t.Errorf("topic contract = %q, want the recorded payloadType", got)
	}
}

// A record without payloadType keeps the derivation: invoice-created is
// InvoiceCreated on invoice-created.
func TestAssembleDerivesThePayloadTypeWithoutARecordedOne(t *testing.T) {
	model, err := Assemble([]template.ScaffoldEntry{extractor("invoices", "invoices", "invoice-created")}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}
	m := model.Messages[0]
	if m.Contract != "InvoiceCreated" || m.Topic != "invoice-created" {
		t.Errorf("message = %+v, want InvoiceCreated on invoice-created", m)
	}
	if _, listed := ComponentEntry(model.Components[0])[template.KeyPublications]; listed {
		t.Error("a single-message producer's entry should carry no publications")
	}
}

// The Ladok extractor publishes seven messages on one topic. Every one is a
// system message on the extractor's channel, the component entry lists them
// for the host, and a loader may route one published beside publishes.
func TestAssemblePublishesEveryPublicationOnTheRecordsChannel(t *testing.T) {
	e := channeled("ladok-extractor", "se.ladok.studiedeltagande.antagning.created.v1", "ladok-events")
	e.Values[template.KeyPayloadType] = "AntagningCreated"
	e.Values[template.KeyPublications] = []any{
		map[string]any{template.KeyMessage: "se.ladok.studiedeltagande.antagning.created.v1"},
		map[string]any{template.KeyMessage: "se.ladok.studiedeltagande.antagning.deleted.v1", template.KeyPayloadType: "AntagningDeleted"},
		map[string]any{template.KeyMessage: "se.ladok.studiedeltagande.registrering.created.v1"},
	}
	l := routingLoader("deleted-loader", "ladok-events", "", template.Route{Message: "se.ladok.studiedeltagande.antagning.deleted.v1"})

	model, err := Assemble([]template.ScaffoldEntry{e, l}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}
	got := map[string]string{}
	for _, m := range model.Messages {
		if m.Topic != "ladok-events" || m.Publisher != "ladok-extractor" {
			t.Errorf("message %+v, want ladok-extractor on ladok-events", m)
		}
		got[m.Name] = m.Contract
	}
	want := map[string]string{
		"se.ladok.studiedeltagande.antagning.created.v1":     "AntagningCreated",
		"se.ladok.studiedeltagande.antagning.deleted.v1":     "AntagningDeleted",
		"se.ladok.studiedeltagande.registrering.created.v1": "SeLadokStudiedeltagandeRegistreringCreatedV1",
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("messages = %v, want %v", got, want)
	}
	wantNames := []any{
		"se.ladok.studiedeltagande.antagning.created.v1",
		"se.ladok.studiedeltagande.antagning.deleted.v1",
		"se.ladok.studiedeltagande.registrering.created.v1",
	}
	if entry := ComponentEntry(model.Components[0]); !reflect.DeepEqual(entry[template.KeyPublications], wantNames) {
		t.Errorf("publications = %#v, want %#v", entry[template.KeyPublications], wantNames)
	}
	if model.Topics[0].Contract != "" {
		t.Errorf("topic contract = %q, want none for a topic carrying several types", model.Topics[0].Contract)
	}
}

func TestAssemblePublicationsErrors(t *testing.T) {
	for _, tc := range []struct {
		name         string
		publications []any
		payloadType  string
		want         string
	}{
		{"publishes missing from the list",
			[]any{map[string]any{template.KeyMessage: "b"}}, "",
			`does not name the published message "a"`},
		{"a message twice",
			[]any{map[string]any{template.KeyMessage: "a"}, map[string]any{template.KeyMessage: "a"}}, "",
			`names message "a" twice`},
		{"entry without message",
			[]any{map[string]any{template.KeyPayloadType: "A"}}, "",
			"publications[0].message is missing"},
		{"list contradicts payloadType",
			[]any{map[string]any{template.KeyMessage: "a", template.KeyPayloadType: "Other"}}, "A",
			`types "a" as "Other", but values.payloadType is "A"`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			e := extractor("x", "x", "a")
			e.Values[template.KeyPublications] = tc.publications
			if tc.payloadType != "" {
				e.Values[template.KeyPayloadType] = tc.payloadType
			}
			_, err := Assemble([]template.ScaffoldEntry{e}, discardWarnf)
			if err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("err = %v, want %q", err, tc.want)
			}
		})
	}
}

// Two producers may not type one message differently, recorded types included.
func TestAssembleRefusesConflictingRecordedPayloadTypes(t *testing.T) {
	a := extractor("a", "a", "order-created")
	b := extractor("b", "b", "order-created")
	b.Values[template.KeyPayloadType] = "OrderCreatedV2"
	_, err := Assemble([]template.ScaffoldEntry{a, b}, discardWarnf)
	if err == nil || !strings.Contains(err.Error(), "conflicting contracts") {
		t.Fatalf("err = %v, want the contract conflict", err)
	}
}

