package main

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// ladokExport is a registry export shaped like the one that declares the
// Ladok messages: seven messages in one group, produced on one channel, plus a
// group whose messages two producers publish on different topics.
const ladokExport = `{
  "specversion": "1.0-rc2x",
  "registryid": "intropy",
  "messagegroups": {
    "se.ladok.studiedeltagande": {
      "messagegroupid": "se.ladok.studiedeltagande",
      "messages": {
%s
      }
    },
    "se.ladok.split": {
      "messagegroupid": "se.ladok.split",
      "messages": {
        "se.ladok.split.thing.v1": {"messageid": "se.ladok.split.thing.v1", "versions": {"1": {"versionid": "1", "isdefault": true}}}
      }
    }
  },
  "endpoints": {
    "ladok-extractor": {
      "endpointid": "ladok-extractor",
      "usage": ["producer"],
      "channel": "students-pubsub/ladok-events",
      "messagegroups": ["/messagegroups/se.ladok.studiedeltagande"]
    },
    "split-a": {"endpointid": "split-a", "usage": ["producer"], "channel": "students-pubsub/split-a", "messagegroups": ["/messagegroups/se.ladok.split"]},
    "split-b": {"endpointid": "split-b", "usage": ["producer"], "channel": "students-pubsub/split-b", "messagegroups": ["/messagegroups/se.ladok.split"]}
  },
  "schemagroups": {
    "se.ladok": {
      "schemagroupid": "se.ladok",
      "schemas": {
        "antagning-created.v1": {
          "schemaid": "antagning-created.v1",
          "versions": {"1": {"versionid": "1", "isdefault": true, "xid": "/schemagroups/se.ladok/schemas/antagning-created.v1/versions/1"}}
        }
      }
    }
  }
}`

var ladokMessages = []string{
	"se.ladok.studiedeltagande.antagning.created.v1",
	"se.ladok.studiedeltagande.antagning.deleted.v1",
	"se.ladok.studiedeltagande.antagning.updated.v1",
	"se.ladok.studiedeltagande.registrering.created.v1",
	"se.ladok.studiedeltagande.registrering.deleted.v1",
	"se.ladok.studiedeltagande.avbrott.created.v1",
	"se.ladok.studiedeltagande.atagande.created.v1",
}

func ladokExportJSON() string {
	entries := make([]string, len(ladokMessages))
	for i, m := range ladokMessages {
		schema := ""
		if i == 0 {
			schema = `, "dataschemaxid": "/schemagroups/se.ladok/schemas/antagning-created.v1"`
		}
		entries[i] = fmt.Sprintf(`        %q: {"messageid": %q, "versions": {"1": {"versionid": "1", "isdefault": true, "envelope": "CloudEvents/1.0", "envelopemetadata": {"type": {"value": %q, "required": true}}%s}}}`, m, m, m, schema)
	}
	return fmt.Sprintf(ladokExport, strings.Join(entries, ",\n"))
}

func ladokRegistryURL(t *testing.T) string {
	t.Helper()
	mux := http.NewServeMux()
	mux.HandleFunc("GET /export", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, ladokExportJSON())
	})
	tsvc := httptest.NewServer(mux)
	t.Cleanup(tsvc.Close)
	return tsvc.URL
}

func ladokDoc(t *testing.T) *xregistry.Export {
	t.Helper()
	var doc xregistry.Export
	if err := json.Unmarshal([]byte(ladokExportJSON()), &doc); err != nil {
		t.Fatal(err)
	}
	return &doc
}

func TestRegistryTopic(t *testing.T) {
	doc := ladokDoc(t)
	for _, tc := range []struct {
		name, message, explicit, want, wantErr string
	}{
		{name: "registry message takes its producer channel's topic",
			message: "se.ladok.studiedeltagande.antagning.created.v1", want: "ladok-events"},
		{name: "every sibling on the channel takes the same topic",
			message: "se.ladok.studiedeltagande.atagande.created.v1", want: "ladok-events"},
		{name: "an explicit topic agreeing with the registry",
			message: "se.ladok.studiedeltagande.antagning.created.v1", explicit: "ladok-events", want: "ladok-events"},
		{name: "an explicit topic contradicting the registry",
			message: "se.ladok.studiedeltagande.antagning.created.v1", explicit: "mine",
			wantErr: `topic "mine" conflicts with the registry: se.ladok.studiedeltagande.antagning.created.v1 is produced on students-pubsub/ladok-events`},
		{name: "several producer channels need a choice",
			message: "se.ladok.split.thing.v1",
			wantErr: "has 2 producer channels in the registry: students-pubsub/split-a, students-pubsub/split-b\npass --set topic=<topic> to choose one"},
		{name: "a choice among several producer channels",
			message: "se.ladok.split.thing.v1", explicit: "split-b", want: "split-b"},
		{name: "a message the registry does not declare keeps the default",
			message: "invoice-created", want: ""},
		{name: "an explicit topic for a message the registry does not declare passes through",
			message: "invoice-created", explicit: "invoices", want: ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got, err := registryTopic(doc, tc.message, tc.explicit)
			if tc.wantErr != "" {
				var ue *usageError
				if !errors.As(err, &ue) || !strings.Contains(err.Error(), tc.wantErr) {
					t.Fatalf("err = %v, want usage error containing %q", err, tc.wantErr)
				}
				return
			}
			if err != nil || got != tc.want {
				t.Fatalf("registryTopic = %q, %v; want %q", got, err, tc.want)
			}
		})
	}
}

func TestResolveMessageChannel(t *testing.T) {
	t.Run("the configured registry decides the topic", func(t *testing.T) {
		withConfig(t, "")
		withRegistryURL(t, ladokRegistryURL(t))
		got, err := resolveMessageChannel(context.Background(), &bytes.Buffer{}, "se.ladok.studiedeltagande.antagning.created.v1", map[string]any{})
		if err != nil || got != "ladok-events" {
			t.Fatalf("channel = %q, %v; want ladok-events", got, err)
		}
	})

	t.Run("--set channel is checked like --set topic", func(t *testing.T) {
		withConfig(t, "")
		withRegistryURL(t, ladokRegistryURL(t))
		_, err := resolveMessageChannel(context.Background(), &bytes.Buffer{}, "se.ladok.studiedeltagande.antagning.created.v1", map[string]any{"channel": "mine"})
		if err == nil || !strings.Contains(err.Error(), "conflicts with the registry") {
			t.Fatalf("err = %v, want the registry conflict", err)
		}
	})

	t.Run("no registry configured keeps the template default", func(t *testing.T) {
		withConfig(t, "")
		t.Setenv("INTROPY_REGISTRY_URL", "")
		got, err := resolveMessageChannel(context.Background(), &bytes.Buffer{}, "se.ladok.studiedeltagande.antagning.created.v1", map[string]any{})
		if err != nil || got != "" {
			t.Fatalf("channel = %q, %v; want the template default", got, err)
		}
	})

	t.Run("an unreachable registry warns and keeps the template default", func(t *testing.T) {
		withConfig(t, "")
		withRegistryURL(t, "http://127.0.0.1:1")
		var stderr bytes.Buffer
		got, err := resolveMessageChannel(context.Background(), &stderr, "invoice-created", map[string]any{})
		if err != nil || got != "" {
			t.Fatalf("channel = %q, %v; want the template default", got, err)
		}
		if !strings.Contains(stderr.String(), "warning:") || !strings.Contains(stderr.String(), "invoice-created is wired on the template's default topic") {
			t.Errorf("stderr = %q, want the warning", stderr.String())
		}
	})

	t.Run("no message flag never reads the registry", func(t *testing.T) {
		withConfig(t, "")
		withRegistryURL(t, "http://127.0.0.1:1")
		var stderr bytes.Buffer
		if got, err := resolveMessageChannel(context.Background(), &stderr, "", map[string]any{}); err != nil || got != "" || stderr.Len() != 0 {
			t.Fatalf("channel = %q, %v, stderr %q", got, err, stderr.String())
		}
	})
}

// A workspace record publishing a registry message no longer hides the
// registry's definition: show prints the workspace entry, with its recorded
// contract and topic, then the registry's envelope and schema.
func TestMessageShowWorkspaceMessageAlsoShowsTheRegistryDefinition(t *testing.T) {
	withConfig(t, "")
	withRegistryURL(t, ladokRegistryURL(t))
	tmp := t.TempDir()
	t.Chdir(tmp)
	if err := os.MkdirAll(filepath.Join(tmp, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	writeFileT(t, tmp+"/.intropy/scaffold.json", `{"schemaVersion":1,"template":"extractor","owner":"o","repo":"r","version":"v2.3.0","blockKind":"extractor","values":{"appId":"ladok-extractor","publishes":"se.ladok.studiedeltagande.antagning.created.v1","payloadType":"AntagningCreated","channel":"ladok-events"}}`+"\n")

	stdout, _ := runMessage(t, "show", "se.ladok.studiedeltagande.antagning.created.v1")
	out := stdout.String()
	for _, want := range []string{
		"source:    workspace",
		"contract:  AntagningCreated",
		"topic:     ladok-events",
		"source:    registry",
		"group:     se.ladok.studiedeltagande",
		"channels:  students-pubsub/ladok-events",
		"dataschema: /schemagroups/se.ladok/schemas/antagning-created.v1",
		"envelope type: se.ladok.studiedeltagande.antagning.created.v1 (required)",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("show output missing %q:\n%s", want, out)
		}
	}

	stdout, _ = runMessage(t, "show", "se.ladok.studiedeltagande.antagning.created.v1", "--output", "json")
	var e MessageEntry
	if err := json.Unmarshal(stdout.Bytes(), &e); err != nil {
		t.Fatalf("parse json: %v", err)
	}
	if e.Source != messageSourceWorkspace || e.Registry == nil || e.Registry.Group != "se.ladok.studiedeltagande" {
		t.Errorf("json = %+v, want the workspace entry carrying the registry definition", e)
	}
}

