// warnForeignProducers warns about each message the system publishes that the
// registry says another system's pub/sub produces. Producer and consumers
// live in one system for now, so such a message means a misnamed system or a
// second producer. It never fails: the registry may lag a rename, and the
// topic, which is what the broker routes on, is already the registry's. No
// registry, or nothing published, is nothing to check; an unreachable registry
// is one warning.
func warnForeignProducers(ctx context.Context, stderr io.Writer, m *system.Model) {
	var published []system.Message
	for _, msg := range m.Messages {
		if msg.Publisher != "" && msg.Pubsub != "" {
			published = append(published, msg)
		}
	}
	if len(published) == 0 {
		return
	}
	url, err := resolveRegistryURL("")
	if err != nil {
		return
	}
	client, err := newXRegistryClient(url)
	if err != nil {
		fmt.Fprintf(stderr, "warning: %v\n", err)
		return
	}
	doc, err := client.Export(ctx)
	if err != nil {
		fmt.Fprintf(stderr, "warning: published messages not checked against the registry: %v\n", err)
		return
	}
	for _, w := range foreignProducers(doc, published) {
		fmt.Fprintf(stderr, "warning: %s\n", w)
	}
}

// foreignProducers lists, as warnings, the messages whose registry producer
// channels name a pub/sub other than the one the system publishes them on. A
// message the registry does not know, or one with no producer channel, is not
// reported.
func foreignProducers(doc *xregistry.Export, published []system.Message) []string {
	var out []string
	for _, msg := range published {
		_, group, err := xregistry.FindMessage(doc, msg.Name)
		if err != nil {
			continue
		}
		channels := xregistry.ProducerChannels(doc, group.ID)
		if len(channels) == 0 {
			continue
		}
		own := false
		for _, c := range channels {
			if pubsub, _, err := xregistry.SplitChannel(c); err == nil && pubsub == msg.Pubsub {
				own = true
				break
			}
		}
		if !own {
			out = append(out, fmt.Sprintf("%s is produced on %s in the registry, but this system publishes it on %s\ncheck the system name, or whether another system already produces it",
				msg.Name, strings.Join(channels, ", "), msg.Pubsub))
		}
	}
	return out
}

// warnUnpublishedSubscription warns when a consumer is scaffolded for a message
// no component in its workspace publishes yet. It is a warning because the
// producer may be scaffolded next; sys create is where it becomes an error.
func warnUnpublishedSubscription(stderr io.Writer, facts *template.WorkspaceFacts, message string) {
	if message == "" {
		return
	}
	if _, published := facts.ContractForMessage(message); published {
		return
	}
	fmt.Fprintf(stderr, "warning: no component in this workspace publishes %s yet\n'intropy sys create' needs its producer in this system; subscribing to a message another system produces is not supported yet\n", message)
}
