// sys update refreshes publications like every other wiring key: a list the
// scaffold no longer implies leaves the stored entry.
func TestRefreshedEntryDropsPublicationsTheScaffoldNoLongerLists(t *testing.T) {
	before, err := Assemble([]template.ScaffoldEntry{multiPublisher("sales-extractor", "order-created", "order-cancelled")}, discardWarnf)
	if err != nil {
		t.Fatal(err)
	}
	stored := storedEntry(t, before.Components[0])
	if _, ok := stored[template.KeyPublications]; !ok {
		t.Fatalf("stored entry = %#v, want publications", stored)
	}
	after, err := Assemble([]template.ScaffoldEntry{channeled("sales-extractor", "order-created", "sales-events")}, discardWarnf)
	if err != nil {
		t.Fatal(err)
	}
	if got := refreshedEntry(stored, after.Components[0]); got[template.KeyPublications] != nil {
		t.Errorf("refreshed = %#v, want publications gone", got)
	}
}

