func TestForeignProducers(t *testing.T) {
	doc := salesDoc(t)
	published := func(name, pubsub string) []system.Message {
		return []system.Message{{Name: name, Publisher: "x", Pubsub: pubsub, Topic: "sales-events"}}
	}
