		!strings.Contains(got[0], "\ncheck the system name, or whether another system already produces it") {
		t.Errorf("foreign pub/sub: warnings = %v", got)
	}
	if got := foreignProducers(doc, published("invoice-created", "orders-pubsub")); len(got) != 0 {
		t.Errorf("message unknown to the registry: warnings = %v, want none", got)
	}
}

func TestWarnForeignProducers(t *testing.T) {
	model := &system.Model{Messages: []system.Message{
		{Name: "com.example.sales.order.created.v1", Publisher: "x", Pubsub: "orders-pubsub", Topic: "sales-events"},
	}}

	t.Run("the configured registry is consulted", func(t *testing.T) {
		withConfig(t, "")
		withRegistryURL(t, salesRegistryURL(t))
		var stderr bytes.Buffer
		warnForeignProducers(context.Background(), &stderr, model)
		if !strings.Contains(stderr.String(), "warning: com.example.sales.order.created.v1 is produced on sales-pubsub/sales-events") {
			t.Errorf("stderr = %q", stderr.String())
		}
	})

	t.Run("no registry configured checks nothing", func(t *testing.T) {
		withConfig(t, "")
		t.Setenv("INTROPY_REGISTRY_URL", "")
		var stderr bytes.Buffer
		warnForeignProducers(context.Background(), &stderr, model)
		if stderr.Len() != 0 {
			t.Errorf("stderr = %q, want nothing", stderr.String())
		}
	})

	t.Run("an unreachable registry warns once", func(t *testing.T) {
		withConfig(t, "")
		withRegistryURL(t, "http://127.0.0.1:1")
		var stderr bytes.Buffer
		warnForeignProducers(context.Background(), &stderr, model)
		if got := strings.Count(stderr.String(), "warning:"); got != 1 || !strings.Contains(stderr.String(), "not checked against the registry") {
			t.Errorf("stderr = %q, want one warning", stderr.String())
		}
	})

	t.Run("a subscriber-only system checks nothing", func(t *testing.T) {
		withConfig(t, "")
		withRegistryURL(t, "http://127.0.0.1:1")
		var stderr bytes.Buffer
		warnForeignProducers(context.Background(), &stderr, &system.Model{})
		if stderr.Len() != 0 {
			t.Errorf("stderr = %q, want nothing", stderr.String())
		}
	})
}

func TestWarnUnpublishedSubscription(t *testing.T) {
	facts := template.BuildWorkspaceFacts([]template.WorkspaceFactEntry{
		{BlockKind: template.BlockKindExtractor, Values: map[string]any{template.KeyPublishes: "order-created"}},
	})
